# [SAME-SCENARIO] stream_chunks.py\n# Streams audio chunks from an async iterable source (e.g., an async generator)\n# and sends them to IBM Watson Speech to Text WebSocket for real-time transcription.\n# Provider credentials are obtained from environment variables.\n\nimport asyncio\nimport json\nimport os\nimport sys\nfrom ibm_watson import SpeechToTextV1\nfrom ibm_watson.websocket import RecognizeCallback, AudioSource\nimport sounddevice as sd\n\nclass ChunkedSpeechStream:\n    def __init__(self, apikey: str, url: str, chunk_size: int = 1024):\n        self.speech_to_text = SpeechToTextV1(auth_type='iam',\n                                             apikey=apikey,\n                                             url=url)\n        self.chunk_size = chunk_size\n        # Watson STT expects audio/l16 16kHz 16-bit mono PCM encoded as bytes.\n    async def stream_from_microphone(self):\n        # Create WebSocket RecognizeCallback\n        recognize_callback = RecognizeCallback(self._on_connect,\n                                               self._on_data,\n                                               self._on_error,\n                                               self._on_close,\n                                               audio_format='audio/l16;rate=16000')\n        # Microphone audio generator\n        async def microphone_generator():\n            with sd.InputStream(samplerate=16000, channels=1, callback=sd.CallbackFlags):\n                while True:\n                    data = sd.rec(self.chunk_size, samplerate=16000, channels=1, blocking=True)\n                    yield data.tobytes()\n        # Start recognition asynchronously\n        asyncio.create_task(recognize_callback.recognize(self.speech_to_text._service.url, microphone_generator()))\n        # Keep the process alive\n        await asyncio.Event().wait()\n\n    def _on_connect(self):\n        print('Connected to Watson STT')\n\n    def _on_data(self, json_data):\n        results = json.loads(json_data)\n        for result in results.get('results', []):\n            alternatives = result.get('alternatives', [])\n            if alternatives:\n                transcript = alternatives[0].get('transcript', '')\n                print('Chunk result:', transcript)\n            else:\n                print('No alternatives in chunk')\n\n    def _on_error(self, error):\n        print('Error during streaming:', error)\n\n    def _on_close(self):\n        print('WebSocket closed')\n\nif __name__ == '__main__:\n    apikey = os.getenv('IBM_STT_APIKEY')\n    url = os.getenv('IBM_STT_URL')\n    if not apikey or not url:\n        print('Set IBM_STT_APIKEY and IBM_STT_URL environment variables')\n        sys.exit(1)\n    streamer = ChunkedSpeechStream(apikey, url)\n    asyncio.run(streamer.stream_from_microphone())\n